  "overview": {
    "text": "Tinker v. Des Moines Independent Community School District is a 1969 U.S. Supreme Court case about whether public-school students could express political views at school. In December 1965, Iowa students Mary Beth and John Tinker and Christopher Eckhardt wore black armbands to oppose U.S. involvement in Vietnam and support a truce; school officials suspended them under a ban on armbands. On February 24, 1969, the Court ruled 7–2 for the students, finding their quiet, non-disruptive protest protected by the First Amendment, applied to state schools through the Fourteenth Amendment. The decision is significant for recognizing student expression rights while allowing schools to restrict speech that materially disrupts schoolwork or interferes with others’ rights.",
    "source_urls": [
      "https://tile.loc.gov/storage-services/service/ll/usrep/usrep393/usrep393503/usrep393503.pdf",
      "https://www.uscourts.gov/about-federal-courts/educational-resources/educational-activities/first-amendment-activities/tinker-v-des-moines/facts-and-case-summary-tinker-v-des-moines"
    ]
  },
  "key_facts": [
    {
      "text": "The Supreme Court decided the case on February 24, 1969, ruling 7–2 for the students.",
      "source_urls": [
        "https://www.uscourts.gov/about-federal-courts/educational-resources/educational-activities/first-amendment-activities/tinker-v-des-moines/facts-and-case-summary-tinker-v-des-moines"
      ]
    },
    {
      "text": "The students planned to wear black armbands to oppose U.S. hostilities in Vietnam and show support for a truce.",
      "source_urls": [
        "https://tile.loc.gov/storage-services/service/ll/usrep/usrep393/usrep393503/usrep393503.pdf"
      ]
    },
    {
      "text": "School officials adopted a policy requiring students to remove armbands or face suspension; Mary Beth Tinker, Christopher Eckhardt, and John Tinker were suspended.",
      "source_urls": [
        "https://tile.loc.gov/storage-services/service/ll/usrep/usrep393/usrep393503/usrep393503.pdf"
      ]
    },
    {
      "text": "The Court found the students’ quiet, passive expression protected in the circumstances because it did not disrupt school or infringe others’ rights.",
      "source_urls": [
        "https://tile.loc.gov/storage-services/service/ll/usrep/usrep393/usrep393503/usrep393503.pdf"
      ]
    },
    {
      "text": "The Library of Congress describes the decision as a continuing reference point for assessing whether school discipline violates students’ First Amendment rights.",
      "source_urls": [
        "https://wwws.loc.gov/exhibits/creating-the-united-states/bill-of-rights-legacy.html"
      ]
    }
  ],
